/**
 * push-sw.js — Web Push handlers, pulled into the generated service worker via
 * `workbox.importScripts` in vite.config.ts.
 *
 * It lives as a separate importScripts file on purpose: vite-plugin-pwa runs in
 * generateSW mode, so the service worker itself is generated by Workbox and
 * cannot be hand-edited. Switching to injectManifest to add these two listeners
 * would mean re-implementing the precache and runtimeCaching setup by hand.
 * importScripts adds the listeners without touching any caching rule.
 *
 * Note: this file is served from /push-sw.js and is also precached by the
 * globPatterns rule, so it updates together with the rest of the app.
 */

/* eslint-env serviceworker */
/* global self, clients */

self.addEventListener('push', event => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    // A push with a non-JSON body should still surface something readable.
    payload = { title: 'TourPilot', body: event.data.text() };
  }

  const title = payload.title || 'TourPilot';
  const options = {
    body: payload.body || '',
    icon: '/logo.svg',
    badge: '/favicon.svg',
    // Collapse repeats of the same entity into one notification.
    tag: payload.relatedType && payload.relatedId
      ? `${payload.relatedType}-${payload.relatedId}`
      : payload.type || 'tourpilot',
    renotify: true,
    data: { url: payload.url || '/notifications' },
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', event => {
  event.notification.close();

  const target = (event.notification.data && event.notification.data.url) || '/notifications';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(windowClients => {
      // Reuse an open TourPilot tab rather than piling up new ones.
      for (const client of windowClients) {
        if (new URL(client.url).origin === self.location.origin && 'focus' in client) {
          if ('navigate' in client) client.navigate(target);
          return client.focus();
        }
      }
      if (clients.openWindow) return clients.openWindow(target);
      return undefined;
    }),
  );
});
